-- Which accounts shift toward overnight remote logons on day 2?
WITH d AS (SELECT user_name,dataset_day,COUNT(*) logons,SUM((hour_of_day<6)::INT) night_logons FROM auth_enriched WHERE success AND remote_logon GROUP BY 1,2), paired AS (SELECT a.user_name,a.logons day1_logons,b.logons day2_logons,ROUND(100.0*a.night_logons/a.logons,2) day1_night_pct,ROUND(100.0*b.night_logons/b.logons,2) day2_night_pct FROM d a JOIN d b ON a.user_name=b.user_name AND a.dataset_day=1 AND b.dataset_day=2 WHERE a.logons>=20 AND b.logons>=20) SELECT * FROM paired ORDER BY day2_night_pct-day1_night_pct DESC, user_name LIMIT 30;
